+    /**
+     * @return array{valid: bool, expired: bool}
+     */
+    public function verify(string $token, OperationRun $operationRun, string $channel, string $purpose): array
+    {
+        $parts = explode('.', $token, 2);
+
+        if (count($parts) !== 2) {
+            return ['valid' => false, 'expired' => false];
+        }
+
+        [$payload, $signature] = $parts;
+
+        if (! hash_equals($this->sign($payload), $signature)) {
+            return ['valid' => false, 'expired' => false];
+        }
+
+        $decoded = json_decode((string) base64_decode($payload, true), true);
+
+        if (! is_array($decoded)) {
+            return ['valid' => false, 'expired' => false];
+        }
+
+        if (($decoded['purpose'] ?? null) !== $purpose) {
+            return ['valid' => false, 'expired' => false];
+        }
+
+        if (($decoded['operation_uuid'] ?? null) !== $operationRun->id) {
+            return ['valid' => false, 'expired' => false];
+        }
+
+        if (($decoded['channel'] ?? null) !== $channel) {
+            return ['valid' => false, 'expired' => false];
+        }
+
+        $expiresAt = $decoded['expires_at'] ?? null;
+
+        if (! is_int($expiresAt)) {
+            return ['valid' => false, 'expired' => false];
+        }
+
+        if (Carbon::createFromTimestamp($expiresAt)->lessThanOrEqualTo(Carbon::now())) {
+            return ['valid' => false, 'expired' => true];
+        }
+
+        return ['valid' => true, 'expired' => false];
+    }
+
+    /**
+     * @return array{token: string, expires_at: Carbon}
+     */
+    private function token(string $purpose, OperationRun $operationRun, string $channel, int $ttlSeconds): array
+    {
+        $expiresAt = Carbon::now()->addSeconds($ttlSeconds);
+        $payload = base64_encode(json_encode([
+            'id' => (string) Str::uuid(),
+            'purpose' => $purpose,
+            'operation_uuid' => $operationRun->id,
+            'channel' => $channel,
+            'expires_at' => $expiresAt->timestamp,
+        ], JSON_THROW_ON_ERROR));
+
+        return [
+            'token' => "{$payload}.{$this->sign($payload)}",
+            'expires_at' => $expiresAt,
+        ];
+    }
